package {
    default_applicable_licenses: ["Android-Apache-2.0"],
}

cc_library {
    name: "libscriptexecutorjni",

    cflags: [
        "-Wno-unused-parameter",
    ],
    header_libs: [
        "jni_headers",
        "libnativehelper_header_only",
    ],

    static_libs: [
        "liblua",
        "libbase",
    ],

    shared_libs: [
        "liblog",
    ],

    srcs: [
        "src/BundleWrapper.cpp",
        "src/JniUtils.cpp",
        "src/LuaEngine.cpp",
        "src/ScriptExecutorJni.cpp",
        "src/ScriptExecutorListener.cpp",
    ],

    min_sdk_version: "30",

    stl: "libc++_static",

    // Allow dependents to use the header files.
    export_include_dirs: ["src"],

    apex_available: [
        "//apex_available:platform",
        "com.android.car.framework",
    ],
}

android_app {
    name: "ScriptExecutor",

    srcs: [
        ":iscriptexecutor_aidl",
        "src/**/*.java",
    ],

    resource_dirs: ["res"],

    sdk_version: "module_current",

    min_sdk_version: "33",

    privileged: false,

    optimize: {
        enabled: false,
    },

    libs: [
        "android.car",
    ],

    jni_libs: [
        "libscriptexecutorjni",
    ],

    jni_uses_platform_apis: true,

    use_embedded_native_libs: true,
    apex_available: [
        "//apex_available:platform",
        "com.android.car.framework",
    ],
}

java_test_helper_library {
    name: "scriptexecutor-test-lib",

    srcs: [
        ":iscriptexecutor_aidl",
        "src/**/*.java",
    ],

    libs: [
        "android.car",
    ],

    sdk_version: "test_current",
}

